import os
import pandas as pd
from langflow.custom import Component
from langflow.io import FileInput, IntInput, MultilineInput, MessageTextInput, Output
from langflow.schema.message import Message


class ExcelCSVtoCSVStrComponent(Component):
    display_name = "Excel/CSV to CSV String"
    description = "Converts an Excel or CSV file to a CSV-formatted string. Accepts both file path and direct CSV content."
    icon = "file"
    name = "ExcelCSVtoCSVStr"

    inputs = [
        MultilineInput(
            name="csv_content",
            display_name="CSV Content",
            info="Direct CSV content as a string.",
        ),
        FileInput(
            name="excel_file_path",
            display_name="Excel/CSV File",
            info="The path to the Excel or CSV file.",
            advanced=True,
        ),
        IntInput(
            name="only_get_first_rows",
            display_name="Max Rows",
            info="Number of rows to read (optional).",
            value=None,
            advanced=True,
        ),
        MessageTextInput(
            name="csv_sep",
            display_name="CSV Separator",
            info="Character used as separator in CSV files.",
            value=";",
            advanced=True,
        ),
    ]

    outputs = [
        Output(display_name="CSV String", name="csv_string", method="convert_to_csv_string"),
    ]

    def convert_to_csv_string(self) -> Message:
        if self.excel_file_path:
            csv_data = self._process_file(self.excel_file_path)
            return Message(text=csv_data, csv_data=csv_data)
        elif self.csv_content:
            csv_data = self._process_csv_string(self.csv_content)
            return Message(text=csv_data, csv_data=csv_data)
        else:
            self.log("No valid input provided.")
            return Message(text="Error: No valid input provided.")

    def _process_file(self, file_path: str) -> str:
        if not os.path.exists(file_path):
            self.log(f"File not found: {file_path}")
            return "Error: File not found."

        _, file_extension = os.path.splitext(file_path)
        if file_extension.lower() not in [".xls", ".xlsx", ".csv"]:
            self.log(f"Invalid file type: {file_extension}")
            return "Error: Invalid file type."

        try:
            if file_extension.lower() == ".csv":
                df = pd.read_csv(file_path, header=None, sep=self.csv_sep)
            else:
                df = pd.read_excel(file_path, header=None)
            
            if self.only_get_first_rows is not None and self.only_get_first_rows > 0:
                df = df.head(self.only_get_first_rows)
            
            return df.to_csv(index=False, header=False, sep=self.csv_sep)
        except Exception as e:
            self.log(f"Error processing file: {e}")
            return f"Error: {str(e)}"

    def _process_csv_string(self, csv_string: str) -> str:
        try:
            from io import StringIO
            df = pd.read_csv(StringIO(csv_string), header=None, sep=self.csv_sep)
            
            if self.only_get_first_rows is not None and self.only_get_first_rows > 0:
                df = df.head(self.only_get_first_rows)
            
            return df.to_csv(index=False, header=False, sep=self.csv_sep)
        except Exception as e:
            self.log(f"Error processing CSV content: {e}")
            return f"Error: {str(e)}"

import pandas as pd
from io import StringIO
from langflow.custom import Component
from langflow.io import MessageTextInput, MultilineInput, IntInput, BoolInput, Output, FileInput
from langflow.schema import Data, DataFrame, Message


class StandardizedDataExtractor(Component):
    display_name = "Standardized Data Extractor"
    description = "Extracts and standardizes data from a CSV file based on a mapping template."
    icon = "table"
    name = "StandardizedDataExtractor"

    inputs = [
        FileInput(
            name="csv_file",
            display_name="CSV File",
            info="Upload the CSV file to be processed.",
            advanced=True,
        ),
        MultilineInput(
            name="csv_content",
            display_name="CSV Content",
            info="Paste the content of the CSV file here.",
            value="{text}",
        ),
        MessageTextInput(
            name="csv_mapping_template",
            display_name="CSV Mapping Template",
            info="JSON-formatted string defining column mappings.",
            required=True,
        ),
        MultilineInput(
            name="table_header_row",
            display_name="Table Header Row",
            info="Row of the header (if applicable).",
            value="{text}",
        ),
        MessageTextInput(
            name="sep",
            display_name="CSV Separator",
            info="Column separator used in the CSV file.",
            value=";",
            advanced=True,
        ),
        MessageTextInput(
            name="encoding",
            display_name="Encoding",
            info="Encoding format of the CSV file.",
            value="utf-8-sig",
            advanced=True,
        ),
        BoolInput(
            name="strip_and_case_insensitive",
            display_name="Strip & Case Insensitive",
            info="Whether to strip whitespace and ignore case when matching columns.",
            value=True,
            advanced=True,
        ),
        IntInput(
            name="append_row_if_higher_than",
            display_name="Append Row If Higher Than",
            info="Minimum number of non-empty values required to append a row.",
            value=2,
            advanced=True,
        ),
        BoolInput(
            name="add_csv_mapping_template_to_last_column",
            display_name="Add Mapping Template Column",
            info="Whether to add the mapping template as a new column.",
            value=True,
            advanced=True,
        ),
    ]

    outputs = [
        Output(display_name="Standardized CSV", name="standardized_csv", method="build_message"),
        Output(display_name="Standardized DataFrame", name="standardized_dataframe", method="build_dataframe"),
        Output(display_name="Standardized Data", name="standardized_data", method="build_data"),
    ]
    
    def build_message(self) -> Message:
        standardized_df = self._process_csv()
        csv_output = standardized_df.to_csv(index=False, sep=self.sep, encoding=self.encoding, lineterminator='\r\n')
        return Message(text=csv_output)
    
    def build_dataframe(self) -> DataFrame:
        standardized_df = self._process_csv()
        df_result = DataFrame(standardized_df)
        self.status = df_result  # store in self.status for logs
        return df_result
    
    def build_data(self) -> Data:
        standardized_df = self._process_csv()
        data_output = standardized_df.to_dict(orient='records')
        self.log(f"list_of_rows: {data_output}")
        return Data(list_of_rows=data_output)

    def _process_csv(self) -> pd.DataFrame:
        header_row_index = self._get_csv_row_number(
            csv_content= self.csv_content,
            row_content = self._remove_last_column(self.table_header_row),
            csv_sep = ";",
        ) - 1

        if self.csv_file:
            try:
                original_df = pd.read_csv(self.csv_file, sep=self.sep, encoding=self.encoding, header=header_row_index)
            except Exception as e:
                self.log(f"Error reading CSV file: {e}")
                return ValueError(text=f"Error reading CSV file: {e}")
        elif self.csv_content:
            try:
                original_df = pd.read_csv(StringIO(self.csv_content), sep=self.sep, encoding=self.encoding, header=header_row_index)
            except Exception as e:
                self.log(f"Error reading CSV content: {e}")
                return ValueError(text=f"Error reading CSV content: {e}")
        else:
            return ValueError(text="No CSV file or content provided.")
        
        
        try:
            csv_mapping_template = eval(self.csv_mapping_template)  # Convert string to dict
        except Exception as e:
            self.log(f"Invalid CSV mapping template: {e}")
            return ValueError(text=f"Error: Invalid mapping template - {e}")
        
        column_map = {}
        for col in original_df.columns:
            processed_name = col.strip().lower() if self.strip_and_case_insensitive else col
            column_map[processed_name] = col
        
        standardized_data = []
        
        for _, row in original_df.iterrows():
            standardized_row = {}
            for standardized_col, original_col in csv_mapping_template.items():
                value = ""
                if original_col:
                    lookup_col = original_col.strip().lower() if self.strip_and_case_insensitive else original_col
                    
                    if lookup_col in column_map:
                        actual_col = column_map[lookup_col]
                        raw_value = row[actual_col]
                        
                        if pd.notna(raw_value):
                            if isinstance(raw_value, float) and raw_value.is_integer():
                                value = int(raw_value)
                            else:
                                value = raw_value.strip() if isinstance(raw_value, str) else raw_value
                    else:
                        self.log(f"Original column '{original_col}' not found in CSV columns")
                        
                standardized_row[standardized_col] = value
            
            non_empty_count = sum(1 for v in standardized_row.values() if v not in ["", None])
            if non_empty_count > self.append_row_if_higher_than:
                standardized_data.append(standardized_row)
        
        if self.add_csv_mapping_template_to_last_column and standardized_data:
            for i, row in enumerate(standardized_data):
                row["CSV_MAPPING_TEMPLATE"] = str(csv_mapping_template) if i == 0 else ""
        
        standardized_df = pd.DataFrame(standardized_data)
        return standardized_df
    
    def _remove_last_column(self, input_string: str, delimiter: str = ';') -> str:
        columns = input_string.split(delimiter)
        if columns:
            columns.pop()
        return delimiter.join(columns)

    def _get_csv_row_number(
        self,
        csv_content: str,
        row_content: str,
        csv_sep: str = ',',
        encoding: str = 'utf-8-sig',
    ) -> int:
        """
        Finds the row number of the specified content in the Excel or CSV file.

        Args:
            csv_content (str): The CSV content.
            row_content (str): The content to find in the file.

        Returns:
            int: The row number of the content in the file.
        """
        if not csv_content:
            self.log("CSV content is empty.")
            raise ValueError("CSV content is empty.")
        try:
            dataFrame = pd.read_csv(StringIO(csv_content), header=None, sep=csv_sep, encoding=encoding)

            # Busca a linha que contém o conteúdo especificado
            matching_rows = dataFrame[dataFrame.apply(lambda row: csv_sep.join(row.astype(str)).strip() == row_content.strip(), axis=1)]

            if matching_rows.empty:
                self.log(f"Content '{row_content}' not found in the file.")
                raise ValueError(f"Content '{row_content}' not found in the file: {csv_content}.")

            row_number = matching_rows.index[0]
            return row_number + 1
        except Exception as e:
            self.log(f"Error finding the row number: {e}")
            raise

from enum import Enum
from typing import cast

from loguru import logger

from langflow.custom import Component
from langflow.io import DataInput, DropdownInput, Output
from langflow.schema import DataFrame


class DataOperation(str, Enum):
    CONCATENATE = "Concatenate"
    APPEND = "Append"
    MERGE = "Merge"
    JOIN = "Join"


class MergeDataComponent(Component):
    display_name = "Combine Data"
    description = "Combines data using different operations"
    icon = "merge"
    MIN_INPUTS_REQUIRED = 2

    inputs = [
        DataInput(name="data_inputs", display_name="Data Inputs", info="Data to combine", is_list=True, required=True),
        DropdownInput(
            name="operation",
            display_name="Operation Type",
            options=[op.value for op in DataOperation],
            value=DataOperation.CONCATENATE.value,
        ),
    ]
    outputs = [Output(display_name="DataFrame", name="combined_data", method="combine_data")]

    def combine_data(self) -> DataFrame:
        if not self.data_inputs or len(self.data_inputs) < self.MIN_INPUTS_REQUIRED:
            empty_dataframe = DataFrame()
            self.status = empty_dataframe
            return empty_dataframe

        operation = DataOperation(self.operation)
        try:
            combined_dataframe = self._process_operation(operation)
            self.status = combined_dataframe
        except Exception as e:
            logger.error(f"Error during operation {operation}: {e!s}")
            raise
        else:
            return combined_dataframe

    def _process_operation(self, operation: DataOperation) -> DataFrame:
        if operation == DataOperation.CONCATENATE:
            combined_data: dict[str, str | object] = {}
            for data_input in self.data_inputs:
                for key, value in data_input.data.items():
                    if key in combined_data:
                        if isinstance(combined_data[key], str) and isinstance(value, str):
                            combined_data[key] = f"{combined_data[key]}\n{value}"
                        else:
                            combined_data[key] = value
                    else:
                        combined_data[key] = value
            return DataFrame([combined_data])

        if operation == DataOperation.APPEND:
            rows = [data_input.data for data_input in self.data_inputs]
            return DataFrame(rows)

        if operation == DataOperation.MERGE:
            result_data: dict[str, str | list[str] | object] = {}
            for data_input in self.data_inputs:
                for key, value in data_input.data.items():
                    if key in result_data and isinstance(value, str):
                        if isinstance(result_data[key], list):
                            cast("list[str]", result_data[key]).append(value)
                        else:
                            result_data[key] = [result_data[key], value]
                    else:
                        result_data[key] = value
            return DataFrame([result_data])

        if operation == DataOperation.JOIN:
            combined_data = {}
            for idx, data_input in enumerate(self.data_inputs, 1):
                for key, value in data_input.data.items():
                    new_key = f"{key}_doc{idx}" if idx > 1 else key
                    combined_data[new_key] = value
            return DataFrame([combined_data])

        return DataFrame()

from langflow.custom import Component
from langflow.io import DataInput, Output
from langflow.schema import Data


class LoopComponent(Component):
    display_name = "Loop"
    description = (
        "Iterates over a list of Data objects, outputting one item at a time and aggregating results from loop inputs."
    )
    icon = "infinity"

    inputs = [
        DataInput(
            name="data",
            display_name="Data",
            info="The initial list of Data objects to iterate over.",
        ),
    ]

    outputs = [
        Output(display_name="Item", name="item", method="item_output", allows_loop=True),
        Output(display_name="Done", name="done", method="done_output"),
    ]

    def initialize_data(self) -> None:
        """Initialize the data list, context index, and aggregated list."""
        if self.ctx.get(f"{self._id}_initialized", False):
            return

        # Ensure data is a list of Data objects
        data_list = self._validate_data(self.data)

        # Store the initial data and context variables
        self.update_ctx(
            {
                f"{self._id}_data": data_list,
                f"{self._id}_index": 0,
                f"{self._id}_aggregated": [],
                f"{self._id}_initialized": True,
            }
        )

    def _validate_data(self, data):
        """Validate and return a list of Data objects."""
        if isinstance(data, Data):
            return [data]
        if isinstance(data, list) and all(isinstance(item, Data) for item in data):
            return data
        msg = "The 'data' input must be a list of Data objects or a single Data object."
        raise TypeError(msg)

    def evaluate_stop_loop(self) -> bool:
        """Evaluate whether to stop item or done output."""
        current_index = self.ctx.get(f"{self._id}_index", 0)
        data_length = len(self.ctx.get(f"{self._id}_data", []))
        return current_index > data_length

    def item_output(self) -> Data:
        """Output the next item in the list or stop if done."""
        self.initialize_data()
        current_item = Data(text="")

        if self.evaluate_stop_loop():
            self.stop("item")
            return Data(text="")

        # Get data list and current index
        data_list, current_index = self.loop_variables()
        if current_index < len(data_list):
            # Output current item and increment index
            try:
                current_item = data_list[current_index]
            except IndexError:
                current_item = Data(text="")
        self.aggregated_output()
        self.update_ctx({f"{self._id}_index": current_index + 1})
        return current_item

    def done_output(self) -> Data:
        """Trigger the done output when iteration is complete."""
        self.initialize_data()

        if self.evaluate_stop_loop():
            self.stop("item")
            self.start("done")

            return self.ctx.get(f"{self._id}_aggregated", [])
        self.stop("done")
        return Data(text="")

    def loop_variables(self):
        """Retrieve loop variables from context."""
        return (
            self.ctx.get(f"{self._id}_data", []),
            self.ctx.get(f"{self._id}_index", 0),
        )

    def aggregated_output(self) -> Data:
        """Return the aggregated list once all items are processed."""
        self.initialize_data()

        # Get data list and aggregated list
        data_list = self.ctx.get(f"{self._id}_data", [])
        aggregated = self.ctx.get(f"{self._id}_aggregated", [])

        # Check if loop input is provided and append to aggregated list
        if self.item is not None and not isinstance(self.item, str) and len(aggregated) <= len(data_list):
            aggregated.append(self.item)
            self.update_ctx({f"{self._id}_aggregated": aggregated})
        return aggregated

